replacements.new:
for (int i = 0; i < 3; i++)
{
    string id = $"{zone.Id}/chest/{i}";
    state.Chests[id] = new Chest
    {
        Id = id, Zone = zone.Id,
        Position = OldFree(zone, new(zone.Spawn.X + 10 + i * 6, zone.Spawn.Y - 8 - i * 3)),
        Kind = i == 0 ? "weathered" : i == 1 ? "locked" : zone.Layer == "Surface" ? "runic" : "ancient",
        Requirement = Math.Clamp(zone.Level, 1, 100), Hidden = i == 2, ReadyAt = 456 + i
    };
}

Assert(state.Chests.Count == catalog.Zones.Count * 3, "The legacy fixture did not recreate every historical ambient chest.");
var loaded = new RealmEngine(catalog, Wire.Copy(state));
Assert(loaded.State.Chests.Count == state.Chests.Count, "Loading discarded historical chest records.");
foreach (var original in state.Chests.Values)
{
    var preserved = loaded.State.Chests[original.Id];
    Assert(preserved.Zone == original.Zone && preserved.Kind == original.Kind
        && preserved.ReadyAt == original.ReadyAt && preserved.Requirement == original.Requirement
        && preserved.Hidden == original.Hidden, "Migration altered non-position chest state: " + original.Id);
}
Assert(loaded.State.Creatures.Values.All(c => WorldMap.Fits(catalog.Zone(c.Zone), c.Position) && WorldMap.Fits(catalog.Zone(c.Zone), c.Home)), "Legacy seeded creature remains blocked.");
